protected attachToTimelineRoot(obj: THREE.Object3D, rootName?: string): void {
  const root = this.ensureTimelineRoot(rootName);
  if (!root) return;
  if (obj.parent && obj.parent !== root) obj.parent.remove(obj);
  root.add(obj);
}

protected resolveAssetPath(assetUrl: string): string {
  const base =
    typeof document !== "undefined"
      ? (document.documentElement?.getAttribute?.("data-base") ?? "")
      : "";
  return `${base}${assetUrl}`.replace(/\/+/g, "/");
}

protected getTimelineRoot(): THREE.Group | null {
  return this._timelineRoot;
}

protected getShaderManager(): ShaderManagerRuntimePort | null {
  const candidate = this._context?.getObject("env.shaderManager.runtime");
  if (!candidate || typeof candidate !== "object") return null;
  const manager = candidate as unknown as ShaderManagerRuntimePort;
  if (typeof manager.register !== "function") return null;
  return manager;
}

protected registerShader(registration: ShaderRegistration): void {
  this.getShaderManager()?.register(registration);
}

protected getShaderOwnerId(): string {
  return this._shaderOwnerId;
}

