}

getTweenApplyMode(): TweenApplyMode {
  return "gsapOnly";
}

setEffects(effects: ObjectEffects): void {
  this._effects = { ...effects };
}

getEffects(): ObjectEffects {
  return this._effects;
}

getBloomEnabled(): boolean {
  return this._effects.bloom?.enabled ?? false;
}

protected ensureTimelineRoot(name?: string): THREE.Group | null {
  if (this._timelineRoot) return this._timelineRoot;
  const scene = this._context?.scene;
  if (!scene) return null;
  const root = new THREE.Group();
  if (name) root.name = name;
  scene.add(root);
  this._timelineRoot = root;
  this._applyOptionVisibility();
  return root;
}

